import{_ as i,o as t,c as a,a2 as h}from"./chunks/framework.62rcL0wY.js";const d=JSON.parse('{"title":"Plugin mở rộng (DLL)","description":"","frontmatter":{},"headers":[],"relativePath":"khai-niem/plugin.md","filePath":"khai-niem/plugin.md"}'),s={name:"khai-niem/plugin.md"};function l(c,n,e,o,g,r){return t(),a("div",null,[...n[0]||(n[0]=[h(`<h1 id="plugin-mo-rong-dll" tabindex="-1">Plugin mở rộng (DLL) <a class="header-anchor" href="#plugin-mo-rong-dll" aria-label="Permalink to &quot;Plugin mở rộng (DLL)&quot;">​</a></h1><p>Trang này giải thích cơ chế hoạt động của plugin trong Clickermann, giao diện hàm C++ để tự viết một plugin DLL, cách gọi plugin bằng lệnh <code>CALL</code> và cảnh báo an toàn.</p><h2 id="plugin-trong-clickermann-la-gi" tabindex="-1">Plugin trong Clickermann là gì? <a class="header-anchor" href="#plugin-trong-clickermann-la-gi" aria-label="Permalink to &quot;Plugin trong Clickermann là gì?&quot;">​</a></h2><p><strong>Plugin</strong> là các mô-đun phần mềm độc lập bên ngoài nhưng có thể giao tiếp với Clickermann để mở rộng khả năng của chương trình.</p><p>Mỗi plugin là một tệp thư viện liên kết động chuẩn của Windows (<strong>DLL</strong>) xuất ra (export) một hàm duy nhất. Bên trong tệp DLL này, ngôn ngữ lập trình và môi trường phát triển dùng để viết DLL đều không quan trọng.</p><h2 id="khuon-mau-ham-xuat-export-function-khi-viet-dll" tabindex="-1">Khuôn mẫu hàm xuất (Export Function) khi viết DLL <a class="header-anchor" href="#khuon-mau-ham-xuat-export-function-khi-viet-dll" aria-label="Permalink to &quot;Khuôn mẫu hàm xuất (Export Function) khi viết DLL&quot;">​</a></h2><p>Bất kể bạn dùng trình biên dịch hay môi trường phát triển nào, tệp DLL của plugin chỉ cần xuất đúng một hàm theo chuẩn C++ như sau:</p><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> execute</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int*</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> _arr</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> _size</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>Trong đó:</p><ul><li>Tên hàm bắt buộc là <code>execute</code>, kiểu trả về là số nguyên <code>int</code>.</li><li>Tham số thứ nhất <code>_arr</code>: con trỏ trỏ tới mảng các số nguyên được truyền từ Clickermann sang plugin.</li><li>Tham số thứ hai <code>_size</code>: số lượng phần tử của mảng <code>_arr</code> (giúp code trong DLL biết giới hạn để không đọc tràn bộ nhớ).</li></ul><p>Cách truyền qua mảng con trỏ này cho phép truyền số lượng tham số số nguyên gần như không giới hạn vào plugin.</p><h2 id="cach-goi-plugin-tu-script-trong-clickermann" tabindex="-1">Cách gọi plugin từ script trong Clickermann <a class="header-anchor" href="#cach-goi-plugin-tu-script-trong-clickermann" aria-label="Permalink to &quot;Cách gọi plugin từ script trong Clickermann&quot;">​</a></h2><p>Trong script <code>.cms</code>, bạn gọi plugin thông qua thủ tục <a href="/clickermann-guide-vi/lenh/kich-ban.html#call"><code>CALL</code></a>:</p><div class="language-cms vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cms</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">CALL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;plugin.dll&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">PRINT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Ket qua: &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">$_return1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">HALT</span></span></code></pre></div><p>Cơ chế thực thi khi gọi <code>CALL</code>:</p><ol><li>Tham số đầu tiên bắt buộc là chuỗi tên tệp DLL của plugin (ví dụ <code>&quot;plugin.dll&quot;</code>), theo sau là danh sách các tham số số nguyên (<code>1, 2, 3</code>).</li><li>Trong lúc hàm <code>execute</code> bên trong plugin đang chạy, script của Clickermann sẽ <strong>đứng chờ</strong> cho đến khi hàm <code>execute</code> hoàn tất rồi mới chạy sang dòng lệnh tiếp theo.</li><li>Giá trị <code>int</code> mà hàm <code>execute</code> trả về sẽ được Clickermann ghi vào biến hệ thống <strong><code>$_return1</code></strong>.</li></ol><h2 id="diem-chua-thong-nhat-ve-thu-muc-dat-tep-dll" tabindex="-1">Điểm chưa thống nhất về thư mục đặt tệp DLL <a class="header-anchor" href="#diem-chua-thong-nhat-ve-thu-muc-dat-tep-dll" aria-label="Permalink to &quot;Điểm chưa thống nhất về thư mục đặt tệp DLL&quot;">​</a></h2><ul><li>🟠 <strong>Vị trí đặt tệp DLL của plugin:</strong><ul><li><strong>Nên làm:</strong> Khi dùng lệnh <code>CALL(&quot;plugin.dll&quot;, ...)</code>, hãy đặt bản sao tệp <code>.dll</code> ở cả thư mục dự án (cùng chỗ với tệp <code>.cms</code>) và thư mục <code>%Clickermann%/plugins/</code>, hoặc kiểm tra xem vị trí nào trả về <code>$_return1</code> đúng trên máy bạn.</li></ul><details class="details custom-block"><summary>Vì sao chưa chắc</summary><ul><li><strong>Theo help, bài Plugin:</strong> Tệp DLL của plugin phải nằm trong <strong>thư mục dự án</strong>, đặt cạnh tệp script đang chạy hoặc trong thư mục con. Nếu không tìm thấy tệp DLL theo tên đã truyền ở đó, lệnh <code>CALL</code> sẽ âm thầm kết thúc.</li><li><strong>Theo sách của Chô tô (tr. 104):</strong> Chỉ ghi rằng tệp DLL đặt cùng thư mục với tệp script.</li><li><strong>Theo help, mục Script và plugin (lệnh <code>CALL</code>):</strong> Lại ghi rằng <code>filename</code> là đường dẫn tương đối tính từ thư mục <strong><code>%Clickermann%/plugins</code></strong>.</li><li>Xem script kiểm chứng tại <a href="/clickermann-guide-vi/phu-luc/can-kiem-tra-tren-windows.html#thu-muc-nap-plugin-dll-cua-call">Cần kiểm tra trên Windows</a>.</li></ul></details></li></ul><h2 id="canh-bao-an-toan-khi-dung-plugin" tabindex="-1">Cảnh báo an toàn khi dùng plugin <a class="header-anchor" href="#canh-bao-an-toan-khi-dung-plugin" aria-label="Permalink to &quot;Cảnh báo an toàn khi dùng plugin&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Cảnh báo từ tác giả Clickermann</p><p>Các tệp plugin <code>.dll</code> là những &quot;hộp đen&quot; chứa mã thực thi máy tính mà người dùng thông thường rất khó kiểm tra bên trong làm gì. Nếu bạn không phải là chuyên gia, <strong>tuyệt đối không sử dụng các tệp plugin <code>.dll</code> tải từ những nguồn không đáng tin cậy</strong>, vì chúng hoàn toàn có thể chứa mã độc gây hại cho máy tính của bạn.</p></div><hr><p><em>Nguồn: Tài liệu trợ giúp <code>help.chm</code> (bài Plugin và mục Script và plugin); tham khảo đối chiếu sách của Chô tô (tr. 104).</em></p>`,22)])])}const u=i(s,[["render",l]]);export{d as __pageData,u as default};
